const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current='nmap',token='',job=null,poll=null,tab='Discovery',hosts=[];
let settings=readObject('studio-settings',{persistHistory:false,safeMode:true});
let history=settings.persistHistory?readSaved('studio-history'):[];
let installedScripts=[];
const state={nmap:{target:'127.0.0.1',scan:'-sT',ports:'',timing:'3',version:true,os:false,defaultScripts:false,traceroute:false,discovery:'',dns:'',scripts:'',scriptArgs:'',exclude:'',extra:'[]'},ncat:{target:'127.0.0.1',port:'8080',mode:'',udp:false,ssl:false,extra:'[]'},nping:{target:'127.0.0.1',mode:'--tcp-connect',port:'80',count:'4',extra:'[]'},ndiff:{first:'',second:'',xml:false,extra:'[]'}};
function readSaved(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch{return []}}
function readObject(key,fallback){try{const value=JSON.parse(localStorage.getItem(key)||'null');return value&&typeof value==='object'&&!Array.isArray(value)?{...fallback,...value}:fallback}catch{return fallback}}
const names={nmap:'Scan builder',scripts:'Script library',results:'Scan results',history:'Scan history',ncat:'Ncat',nping:'Nping',ndiff:'Ndiff',reference:'Tool reference',settings:'Settings'};
const icons={nmap:'⌘',scripts:'▧',results:'▦',history:'◷',ncat:'⇄',nping:'⌁',ndiff:'⊞',reference:'▤',settings:'⚙'};
const field=(id,label,value='',placeholder='')=>`<label for="${id}">${label}</label><input id="${id}" data-key="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}">`;
const select=(id,label,options,value)=>`<label for="${id}">${label}</label><select id="${id}" data-key="${id}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${l}</option>`).join('')}</select>`;
const check=(key,label,s)=>`<label><input data-key="${key}" type="checkbox" ${s[key]?'checked':''}>${label}</label>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function normalizeTargets(value){
 return value.trim().split(/\s+/).filter(Boolean).map(target=>{
  if(/^https?:\/\//i.test(target)){
   let url;try{url=new URL(target)}catch{throw Error('Invalid website URL: '+target)}
   if(!url.hostname)throw Error('The website URL needs a hostname.');
   return url.hostname.replace(/^\[|\]$/g,'');
  }
  if(target.includes('://'))throw Error('Use an HTTP/HTTPS URL, hostname, IP address, or CIDR range.');
  if(/^[a-z0-9.-]+\/$/i.test(target))return target.slice(0,-1);
  return target;
 });
}
function args(){let s=state[current],a=[];if(!s)return[];if(current==='nmap'){a=[s.scan,'-T'+s.timing];if(s.ports)a.push('-p',s.ports);for(const [k,f]of Object.entries({version:'-sV',os:'-O',defaultScripts:'-sC',traceroute:'--traceroute'}))if(s[k])a.push(f);if(s.discovery)a.push(s.discovery);if(s.dns)a.push(s.dns);if(s.scripts)a.push('--script',s.scripts);if(s.scriptArgs)a.push('--script-args',s.scriptArgs);if(s.exclude)a.push('--exclude',s.exclude)}if(current==='ncat'){if(s.mode)a.push(s.mode);if(s.udp)a.push('-u');if(s.ssl)a.push('--ssl')}if(current==='nping'){a=[s.mode,'-c',s.count];if(s.port&&['--tcp','--tcp-connect','--udp'].includes(s.mode))a.push('-p',s.port)}if(current==='ndiff'){if(s.xml)a.push('--xml')}
const extra=JSON.parse(s.extra||'[]');if(!Array.isArray(extra)||!extra.every(x=>typeof x==='string'))throw Error('Advanced arguments must be a JSON array of strings');a.push(...extra);if(current==='ndiff')a.push(s.first,s.second);else {const targets=normalizeTargets(s.target);if(targets.some(t=>t.startsWith('-')))throw Error('Enter targets without option flags');a.push(...targets);if(current==='ncat')a.push(s.port)}return a.filter(x=>x!=='')}
function cmd(){return current+' '+args().map(x=>/^[\w.,:/=-]+$/.test(x)?x:JSON.stringify(x)).join(' ')}
function update(){try{$('#command').textContent=cmd();$('#argError').textContent='';$('#run').disabled=false}catch(e){$('#argError').textContent=e.message;$('#run').disabled=true}}
function advanced(s){return `<details ${settings.safeMode?'':'open'}><summary>Advanced · all command-line options</summary><div class="mode-box"><label><input id="safeMode" type="checkbox" ${settings.safeMode?'checked':''}> Safe mode</label><p class="hint">Safe mode accepts common scan and connection options. Turn it off only for options you understand.</p></div><p class="hint">Add supported options as a JSON argument array. Commands run as argument lists without a shell.</p><label for="extra">Additional arguments</label><textarea id="extra" data-key="extra" spellcheck="false">${esc(s.extra)}</textarea><p class="hint">Example: ["--reason", "--max-retries", "2"] · Advanced mode runs with your account permissions.</p></details>`}
function outputCard(){return `<div class="card"><div class="card-head"><h2>Live output <span class="pill" id="jobStatus">${job ? (job.done ? (job.code===0 ? 'COMPLETE' : 'EXIT '+job.code) : 'RUNNING') : 'READY'}</span></h2><div class="actions"><button class="primary" id="executeHere">▶ Execute</button><button id="stop">■ Stop</button><button id="export">↓ Export</button></div></div><pre class="terminal output" id="output">${esc(job?.output||'Click Execute below to start this command here.\nLive results will appear in this panel.')}</pre><div class="pad"><div class="actions"><input id="stdin" aria-label="Process input" placeholder="Send input to running process" style="flex:1;width:auto"><button id="send">Send ↵</button><button id="eof">Close input</button></div><p class="hint">Raw packet scans and OS detection may need administrator/root privileges.</p></div></div>`}
function builder(){let s=state[current],body='';if(current==='nmap'){body=`<div class="presets">${[['Quick scan','Common TCP ports'],['Discovery','Find active hosts'],['Deep inspection','Services & OS']].map(([n,d])=>`<button class="preset ${n==='Quick scan'?'selected':''}" data-preset="${n}">${n}<span>${d}</span></button>`).join('')}</div>${field('target','Targets',s.target,'Website URL, hostname, IP, or CIDR range')}<p class="hint">Website URLs are converted to hostnames; URL paths and schemes are omitted. Separate targets with spaces. Scan only authorized systems.</p><div class="row">${select('scan','Scan technique',[['-sT','TCP connect'],['-sS','TCP SYN'],['-sU','UDP'],['-sn','Host discovery only'],['-sL','List targets'],['-sA','TCP ACK'],['-sW','TCP Window'],['-sM','Maimon'],['-sN','TCP NULL'],['-sF','TCP FIN'],['-sX','TCP Xmas'],['-sY','SCTP INIT'],['-sZ','SCTP COOKIE ECHO'],['-sO','IP protocol']],s.scan)}${field('ports','Ports',s.ports,'Default ports · e.g. 22,80,443')}</div><div class="checks">${check('version','Service detection',s)}${check('os','OS detection',s)}${check('defaultScripts','Default NSE scripts',s)}${check('traceroute','Traceroute',s)}</div>`}else if(current==='ncat'){body=`<p>Connect, listen, and exchange data with network services.</p><div class="row">${field('target','Host / bind address',s.target)}${field('port','Port',s.port)}</div>${select('mode','Connection mode',[['','Connect'],['--listen','Listen'],['--broker','Connection broker (add --listen)']],s.mode)}<div class="checks">${check('udp','UDP transport',s)}${check('ssl','TLS / SSL',s)}</div>`}else if(current==='nping'){body=`<p>Generate probes and measure network responses.</p>${field('target','Targets',s.target)}${select('mode','Probe protocol',[['--tcp-connect','TCP connect (unprivileged)'],['--tcp','TCP raw'],['--udp','UDP'],['--icmp','ICMP'],['--arp','ARP']],s.mode)}<div class="row">${field('port','Destination ports',s.port)}${field('count','Probe rounds',s.count)}</div>`}else{body=`<p>Compare two Nmap XML reports stored on the local runner.</p>${field('first','Baseline XML path',s.first,'C:/scans/before.xml')}${field('second','Current XML path',s.second,'C:/scans/after.xml')}<div class="checks">${check('xml','Produce XML diff',s)}</div>`}
$('#page').innerHTML=`<div class="grid"><div><div class="card"><div class="card-head"><h2><span class="step">01</span>${current==='nmap'?'Configure your scan':'Configure '+current}</h2><span class="hint">${current.toUpperCase()}</span></div><div class="pad">${body}</div>${current==='nmap'?`<div class="tabs">${['Discovery','Timing','Scripts'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div><div class="pad" id="options"></div>`:''}<div class="pad" style="padding-top:0">${advanced(s)}</div></div>${outputCard()}</div><div><div class="card"><div class="card-head"><h2><span class="step">02</span>Command preview</h2><span class="pill">LIVE</span></div><pre class="terminal" id="command"></pre><div class="pad"><div class="summary-line"><span>Execution</span><b>${token?'Local runner':'Command builder'}</b></div><div class="summary-line"><span>Tool</span><b>${current}</b></div><div id="argError" class="danger"></div><button class="primary run" id="run">▷ ${current==='nmap'?'Run scan':'Run command'}</button><div class="actions"><button id="copy">Copy command</button><button id="copyArgs">Copy argv</button></div></div></div><div class="card tip pad"><h3>Every option, within reach.</h3><p>The form covers common workflows. Advanced arguments expose the full installed CLI, including custom NSE scripts, packet options, output formats, and local files.</p></div><div class="card pad"><h3>Saved profiles</h3><div id="profiles"></div></div></div></div>`;
if(current==='nmap')options();bind();update();renderProfiles();$('#run').onclick=start;$('#executeHere').onclick=start;$('#safeMode').onchange=e=>{settings.safeMode=e.target.checked;localStorage.setItem('studio-settings',JSON.stringify(settings));update()};$('#copy').onclick=()=>navigator.clipboard.writeText(cmd()).then(()=>toast('Command copied'));$('#copyArgs').onclick=()=>navigator.clipboard.writeText(JSON.stringify(args())).then(()=>toast('Argument array copied'));$('#stop').onclick=()=>job?api('/api/stop',{id:job.id}).catch(error):toast('No running job');$('#export').onclick=()=>download('nmap-output.txt',$('#output').textContent);$('#send').onclick=()=>send(false);$('#eof').onclick=()=>send(true);document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{Object.assign(s,{scan:b.dataset.preset==='Discovery'?'-sn':'-sT',version:b.dataset.preset!=='Discovery',os:b.dataset.preset==='Deep inspection',defaultScripts:b.dataset.preset==='Deep inspection',ports:'',extra:b.dataset.preset==='Quick scan'?'["--top-ports", "100"]':'[]'});builder()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;builder()})}
function options(){let s=state.nmap;$('#options').innerHTML=tab==='Discovery'?`<div class="row">${select('discovery','Host discovery',[['','Automatic discovery'],['-Pn','Skip discovery (assume online)'],['-PE','ICMP echo'],['-PS','TCP SYN ping'],['-PA','TCP ACK ping'],['-PU','UDP ping']],s.discovery)}${select('dns','DNS resolution',[['','Automatic'],['-n','Never resolve'],['-R','Always resolve']],s.dns)}</div>${field('exclude','Exclude hosts / networks',s.exclude,'e.g. 192.168.1.1')}`:tab==='Timing'?`${select('timing','Timing template',[['0','T0 · Paranoid'],['1','T1 · Sneaky'],['2','T2 · Polite'],['3','T3 · Normal'],['4','T4 · Aggressive'],['5','T5 · Insane']],s.timing)}<p class="hint">More aggressive timing can reduce accuracy on slow or lossy networks.</p>`:`${field('scripts','NSE scripts or categories',s.scripts,'e.g. http-title,ssl-cert')}${field('scriptArgs','Script arguments',s.scriptArgs,'key=value,key2=value2')}<p class="hint">Browse the Script library to add installed scripts.</p>`}
function bind(){document.querySelectorAll('[data-key]').forEach(e=>e.oninput=()=>{state[current][e.dataset.key]=e.type==='checkbox'?e.checked:e.value;update()})}
function error(e){toast(e.message||String(e))}
let starting=false;
function executionMessage(status,text){
 if($('#jobStatus'))$('#jobStatus').textContent=status;
 if($('#executeHere')){$('#executeHere').disabled=starting;$('#executeHere').textContent=starting?'Connecting…':job&&!job.done?'Running…':'▶ Execute';}
 if($('#output'))$('#output').textContent=text;
 if($('#run')){$('#run').disabled=starting;$('#run').textContent=starting?'Connecting…':job&&!job.done?'Running · view output':'▷ '+(current==='nmap'?'Run scan':'Run command');}
}
async function api(path,data){
 let r;try{r=await fetch(path,{method:data?'POST':'GET',cache:'no-store',signal:AbortSignal.timeout(10000),headers:{'Content-Type':'application/json','X-Nmap-Studio-Token':token},body:data?JSON.stringify(data):undefined})}
 catch(e){throw Error('Cannot reach the local runner. Open start.cmd, then try Run again. '+e.message)}
 let j;try{j=await r.json()}catch{throw Error('The server returned an invalid response. Restart the local runner.')}
 if(!r.ok){const e=Error(j.error||'Request failed');e.status=r.status;throw e}return j;
}
async function apiText(path){
 const response=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(10000),headers:{'X-Nmap-Studio-Token':token}});
 if(!response.ok)throw Error('Request failed: '+response.status);
 return response.text();
}
async function start(){
 if(starting)return;
 if(job&&!job.done){$('#output')?.scrollIntoView({behavior:'smooth',block:'center'});toast('A command is running. Its output is shown below; use Stop to cancel.');return}
 starting=true;executionMessage('CONNECTING','Connecting to the local execution service…');
 try{
  const tool=current,a=args();
  if(state[tool]?.target){const normalized=normalizeTargets(state[tool].target).join(' ');if(normalized!==state[tool].target.trim()){state[tool].target=normalized;if($('#target'))$('#target').value=normalized;update();toast('Using hostname: '+normalized+' (URL path and scheme removed)')}}
  if(!await connectRunner())throw Error('Runner is offline. Double-click start.cmd in the app folder, then click Run again.');
  executionMessage('STARTING','Starting '+tool+'…');
  if(!settings.safeMode&&!confirm('Advanced mode can run every option supported by the installed tool with your account permissions. Continue?')){executionMessage('READY','Advanced execution cancelled.');return}
  const j=await api('/api/run',{tool,args:a,safeMode:settings.safeMode,confirmAdvanced:!settings.safeMode});
  job={id:j.id,output:'',done:false,tool,args:a};starting=false;
  executionMessage('RUNNING','Process started. Waiting for output…\nSome scan stages take time before they print results.');
  $('#output')?.scrollIntoView({behavior:'smooth',block:'center'});
  clearInterval(poll);poll=setInterval(refresh,800);await refresh();
 }catch(e){starting=false;executionMessage('ERROR',e.message);if($('#argError'))$('#argError').textContent=e.message;$('#output')?.scrollIntoView({behavior:'smooth',block:'center'});error(e)}
 finally{starting=false;if($('#run'))$('#run').disabled=false;if($('#executeHere'))$('#executeHere').disabled=false}
}
let refreshing=false;
async function refresh(){
 if(refreshing||!job)return;refreshing=true;
 try{
  job=await api('/api/jobs/'+job.id);
  executionMessage(job.done?(job.code===0?'COMPLETE':`EXIT ${job.code}`):'RUNNING',job.output|| (job.done?'Command finished without output.':'Process is running. Waiting for output…'));
  if($('#output'))$('#output').scrollTop=$('#output').scrollHeight;
  if(job.done){clearInterval(poll);if(job.report?.hosts){hosts=job.report.hosts;toast('Structured results are ready in Scan results.')}if(settings.persistHistory){history.unshift({...job,time:new Date().toISOString()});history=history.slice(0,20);try{localStorage.setItem('studio-history',JSON.stringify(history))}catch{toast('History could not be saved; export output to keep it.')}}}
 }catch(e){executionMessage('CONNECTION ERROR',e.message+'\nReconnecting to the running command…');if(e.status===404){clearInterval(poll);job=null}error(e)}finally{refreshing=false}
}
async function send(eof){try{if(!job)throw Error('Start a command first');await api('/api/input',{id:job.id,data:eof?'':$('#stdin').value+'\n',eof});$('#stdin').value=''}catch(e){error(e)}}
function renderProfiles(){const p=readSaved('studio-profiles');$('#profiles').innerHTML=p.length?p.map((x,i)=>`<div class="summary-line"><button data-profile="${i}">${esc(x.name)}</button><button data-delete="${i}" aria-label="Delete profile">×</button></div>`).join(''):'<p class="hint">Save a configuration to use it again.</p>';document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{let x=p[+b.dataset.profile];state[x.tool]=x.state;show(x.tool)});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{p.splice(+b.dataset.delete,1);localStorage.setItem('studio-profiles',JSON.stringify(p));renderProfiles()})}
$('#saveProfile').onclick=()=>{if(!state[current])return toast('Open a tool to save its configuration.');const name=prompt('Profile name');if(name){let p=readSaved('studio-profiles');p.push({name,tool:current,state:structuredClone(state[current])});localStorage.setItem('studio-profiles',JSON.stringify(p));renderProfiles();toast('Profile saved')}};
function scripts(){const catalog=CATALOG.scripts||[];const namesOnly=installedScripts.length?installedScripts:catalog.map(x=>x.name);const details=new Map(catalog.map(x=>[x.name,x]));const list=namesOnly.map(name=>details.get(name)||{name,categories:['installed'],description:'Installed NSE script'});$('#page').innerHTML=`<div class="card pad"><h2>${list.length} installed NSE scripts</h2><p>This list is read from the local Nmap installation when the runner is connected.</p><label for="search">Find a script</label><input class="search" id="search" placeholder="Search e.g. http, discovery, ssl…"><div class="script-list" id="scriptList"></div></div>`;function render(){let q=$('#search').value.toLowerCase();const matched=list.filter(x=>(x.name+' '+x.categories+' '+x.description).toLowerCase().includes(q));$('#scriptList').innerHTML=matched.length?matched.map(x=>`<div class="script"><div><strong>${esc(x.name)}</strong><p>${esc(x.description.slice(0,220))}</p><div class="tag">${esc(x.categories.join(' · '))}</div></div><button data-script="${esc(x.name)}">＋ Add</button></div>`).join(''):'<div class="empty">No matching scripts.</div>';document.querySelectorAll('[data-script]').forEach(b=>b.onclick=()=>{state.nmap.scripts=[...new Set([...state.nmap.scripts.split(',').filter(Boolean),b.dataset.script])].join(',');toast('Added '+b.dataset.script)})}$('#search').oninput=render;render()}
function parseXML(text){const doc=new DOMParser().parseFromString(text,'text/xml');if(doc.querySelector('parsererror')||!doc.querySelector('nmaprun'))throw Error('Choose a valid Nmap XML report');return [...doc.querySelectorAll('host')].map(h=>({address:h.querySelector('address')?.getAttribute('addr')||'Unknown',name:h.querySelector('hostname')?.getAttribute('name')||'',status:h.querySelector('status')?.getAttribute('state')||'unknown',ports:[...h.querySelectorAll('port')].map(p=>({port:p.getAttribute('portid'),protocol:p.getAttribute('protocol'),state:p.querySelector('state')?.getAttribute('state'),service:p.querySelector('service')?.getAttribute('name')||'',product:[p.querySelector('service')?.getAttribute('product'),p.querySelector('service')?.getAttribute('version')].filter(Boolean).join(' ')}))}))}
function results(){let ports=hosts.flatMap(h=>h.ports||[]);$('#page').innerHTML=`<div class="stat-grid"><div class="stat"><span>Hosts imported</span><b>${hosts.length}</b></div><div class="stat"><span>Hosts online</span><b>${hosts.filter(h=>(h.state||h.status)==='up').length}</b></div><div class="stat"><span>Open ports</span><b>${ports.filter(p=>p.state==='open').length}</b></div></div><div class="card"><div class="card-head"><div><h2>Network inventory</h2><p class="hint">Completed Nmap scans appear automatically. You can also import XML up to 10 MB.</p></div><button id="import">↑ Import XML</button><input type="file" accept=".xml" id="xmlFile" hidden></div><div class="pad">${hosts.length?hosts.map(h=>`<h3>${esc(h.address)} ${esc(h.hostname||h.name||'')} <span class="pill">${esc(h.state||h.status)}</span></h3><table><thead><tr><th>PORT</th><th>STATE</th><th>SERVICE</th><th>VERSION</th></tr></thead><tbody>${(h.ports||[]).map(p=>`<tr><td>${esc(p.port+'/'+p.protocol)}</td><td>${esc(p.state)}</td><td>${esc(p.service)}</td><td>${esc([p.product,p.version].filter(Boolean).join(' '))}</td></tr>`).join('')}</tbody></table><br>`).join(''):'<div class="empty"><div class="symbol">◎</div><strong>Your network, in focus.</strong>Run a scan or import a report to explore your results.</div>'}</div></div>`;$('#import').onclick=()=>$('#xmlFile').click();$('#xmlFile').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>10*1024*1024)throw Error('XML files must be 10 MB or smaller.');hosts=parseXML(await file.text());if(hosts.length>2000||hosts.reduce((n,h)=>n+h.ports.length,0)>50000)throw Error('Report exceeds the 2,000 host or 50,000 port limit.');results()}catch(e){error(e)}}}
function showHistory(){$('#page').innerHTML=`<div class="card pad"><div class="card-head"><div><h2>Recent runs</h2><p class="hint">${settings.persistHistory?'Last 20 completed commands saved in this browser.':'History saving is off. Enable it in Settings.'}</p></div><button id="clearHistory">Clear history</button></div>${history.length?history.map((j,i)=>`<div class="script"><div><strong>${esc(j.tool+' '+j.args.join(' '))}</strong><p>${esc(new Date(j.time).toLocaleString())} · Exit ${j.code}</p></div><button data-history="${i}">View output</button></div>`).join(''):'<div class="empty">No saved runs.</div>'}<pre id="historyOutput" class="help"></pre></div>`;$('#clearHistory').onclick=()=>{history=[];localStorage.removeItem('studio-history');showHistory();toast('History cleared')};document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>$('#historyOutput').textContent=history[+b.dataset.history].output)}
function reference(){$('#page').innerHTML=`<div class="card pad"><h2>Installed command reference</h2><p>Help is loaded from the tool installed on this machine.</p>${select('refTool','Tool',[['nmap','Nmap'],['ncat','Ncat'],['nping','Nping'],['ndiff','Ndiff']],'nmap')}<label for="helpSearch">Filter help</label><input id="helpSearch" placeholder="Search options…"><pre class="help" id="help">Loading…</pre><a href="https://nmap.org/book/man.html" target="_blank" rel="noreferrer">Full Nmap manual ↗</a></div>`;let help='';const render=()=>{$('#help').textContent=help.split('\n').filter(x=>x.toLowerCase().includes($('#helpSearch').value.toLowerCase())).join('\n')};const load=async()=>{try{help=await apiText('/api/help/'+$('#refTool').value)}catch{help=CATALOG.help[$('#refTool').value]||'Tool is not installed.'}render()};$('#refTool').onchange=load;$('#helpSearch').oninput=render;load()}
function settingsPage(){$('#page').innerHTML=`<div class="grid"><div class="card pad"><h2>Privacy and execution</h2><div class="checks"><label><input id="persistHistory" type="checkbox" ${settings.persistHistory?'checked':''}> Save completed output in this browser</label><label><input id="defaultSafe" type="checkbox" ${settings.safeMode?'checked':''}> Use Safe mode by default</label></div><p class="hint">Saved output can contain hostnames, addresses, ports, and service versions. History is off by default.</p><div class="actions"><button id="exportProfiles">Export profiles</button><button id="importProfiles">Import profiles</button><input id="profileFile" type="file" accept=".json" hidden><button id="diagnostics">Download diagnostics</button><button class="danger-button" id="shutdown">Stop local runner</button></div></div><div class="card pad"><h2>Security boundaries</h2><p>The runner accepts requests only from this loopback address, requires a per-session token, validates arguments, and never invokes a command shell.</p><p>Only scan systems you own or have permission to test.</p></div></div>`;$('#persistHistory').onchange=e=>{settings.persistHistory=e.target.checked;if(!settings.persistHistory){history=[];localStorage.removeItem('studio-history')}localStorage.setItem('studio-settings',JSON.stringify(settings));toast('Privacy setting saved')};$('#defaultSafe').onchange=e=>{settings.safeMode=e.target.checked;localStorage.setItem('studio-settings',JSON.stringify(settings));toast('Execution setting saved')};$('#exportProfiles').onclick=()=>download('nmap-studio-profiles.json',JSON.stringify(readSaved('studio-profiles'),null,2),'application/json');$('#importProfiles').onclick=()=>$('#profileFile').click();$('#profileFile').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>1024*1024)throw Error('Profile file must be 1 MB or smaller.');const value=JSON.parse(await file.text());if(!Array.isArray(value)||value.length>100||!value.every(x=>x&&typeof x.name==='string'&&x.name.length<=100&&Object.hasOwn(state,x.tool)&&x.state&&typeof x.state==='object'))throw Error('Invalid profile file.');localStorage.setItem('studio-profiles',JSON.stringify(value));toast('Profiles imported')}catch(e){error(e)}};$('#diagnostics').onclick=async()=>{try{download('nmap-studio-diagnostics.log',await apiText('/api/diagnostics'))}catch(e){error(e)}};$('#shutdown').onclick=async()=>{try{await api('/api/shutdown',{});token='';toast('Local runner stopped');setTimeout(connectRunner,500)}catch(e){error(e)}}}
function show(page){current=page;$('#title').textContent=names[page];$('#breadcrumb').textContent=names[page];$('#subtitle').textContent={nmap:'Turn network questions into clear answers.',scripts:'The right script for every investigation.',results:'Explore hosts, ports, and services.',history:'Review output you chose to keep.',ncat:'Your network connection toolkit.',nping:'See how your network responds.',ndiff:'Understand what changed between scans.',reference:'Help from your installed tools.',settings:'Control privacy, execution, and the local runner.'}[page];$('#saveProfile').style.display=state[page]?'':'none';$('#nav').innerHTML=Object.entries(names).map(([k,v])=>`<button data-page="${k}" class="${k===page?'active':''}"><em>${icons[k]}</em>${v}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));if(state[page])builder();else({scripts,results,history:showHistory,reference,settings:settingsPage}[page])()}
async function connectRunner(){
 try {
  const r=await fetch('/api/status',{signal:AbortSignal.timeout(3000),cache:'no-store'});
  if(!r.ok)throw Error('Runner offline');
  const j=await r.json();if(!j.token)throw Error('Runner offline');
  const changed=token!==j.token;token=j.token;
  $('#connection').textContent='Local runner connected';$('#dot').className='on';$('#version').textContent=j.version||'local';
  $('#notice').textContent='Local-only runner · Scan authorized systems only · '+Object.entries(j.tools).map(([k,v])=>k+(v.installed?' ✓':' unavailable')).join(' · ');
  if(changed)api('/api/scripts').then(value=>{installedScripts=value.scripts||[]}).catch(()=>{});
  if(changed&&state[current]&&!starting)builder();
  return true;
 } catch(e) {
  const changed=!!token;token='';$('#dot').className='';
  const local=['127.0.0.1','localhost'].includes(location.hostname);
  $('#connection').textContent=local?'Runner disconnected':'Browser mode';
  $('#notice').innerHTML=local?'Local runner disconnected. Double-click <b>start.cmd</b> in the app folder. This page reconnects automatically.':'To execute inside this UI, <a href="nmap-studio-local.zip"><b>download the local app</b></a>, extract it, and double-click <b>start.cmd</b>.';
  if(changed&&state[current]&&!starting)builder();
  return false;
 }
}
show('nmap');connectRunner();
if(['127.0.0.1','localhost'].includes(location.hostname))setInterval(connectRunner,5000);
